var __index = {"config":{"lang":["en"],"separator":"[\\s\\-]+","pipeline":["stopWordFilter"]},"docs":[{"location":"index.html","title":"\u4e00\u4efd\u6765\u81ea M78 \u661f\u4e91 NIT \u7684\u6307\u5357","text":"<p>\ud83e\udd73Welcome to NIT Book!\ud83e\udd73</p> <p>\u4e25\u8c28\u7684\u8bf4\uff0c\u76ee\u524d\u53ea\u662f\u8ba1\u8f6f\u5b66\u9662</p>"},{"location":"index.html#_1","title":"\u5f00\u7aef","text":"<p>\u6211\u4f9d\u7a00\u8bb0\u5f97 2023 \u5e74\u7684\u590f\uff0c\u6708\u4eae\u5f88\u5706\uff0c\u5f88\u7f8e\u3002 \u6211\u770b\u7740M78 \u661f\u4e91\u5165\u5b66\u6307\u5357\uff0c \u4f46\uff0c\u68a6\u5f88\u77ed\uff0c\u6211\u65e0\u6cd5\u627e\u5230\u3002 \u7136\u800c\uff0c\u5e86\u5e78\u7531\u65e0\u800c\u5f97\u6b64\u3002</p> <p>\u7248\u672c\u65bd\u5de5\u4e2d, \u672a\u53d1\u5e03 Version</p> <ul> <li>\u603b\u4f53\u6846\u67b6\u7ed3\u6784 completed</li> <li>\u8003\u8bc1\u5efa\u8bae/\u8bc1\u4e66 completed</li> <li>\u6821\u56ed\u751f\u6d3b-\u6821\u56ed\u7ed3\u6784 ing\u2026\u2026</li> </ul>"},{"location":"index.html#_2","title":"\u677f\u5757\u8bf4\u660e","text":"<p>\u5404\u677f\u5757\u6846\u67b6\u7b80\u8981\u8bf4\u660e</p> <ul> <li>\u6821\u56ed\u751f\u6d3b\uff1a\u521d\u5165\u6821\u56ed\uff0c\u751f\u6d3b\u904d\u5386</li> <li>\u65b0\u7684\u4f53\u7cfb\uff1a\u65b0\u7684\u89c4\u5219\uff0c\u65b0\u7684\u4e16\u754c</li> <li>\u5173\u4e8e\u8bfe\u5802\uff1a\u4e0a\u4ec0\u4e48\u8bfe\uff0c\u600e\u4e48\u4e0a\u8bfe</li> <li>\u5173\u4e8e\u793e\u56e2\uff1a\u793e\u56e2\u73af\u5883\uff0c\u793e\u56e2\u8d44\u6e90</li> <li>\u8003\u8bc1\u5efa\u8bae\uff1a\u8003\u4ec0\u4e48\u8bc1\uff0c\u4e3a\u4ec0\u4e48\u8003</li> <li>\u81ea\u5b66\u5206\u6790\uff1a\u81ea\u5b66\u4f18\u7f3a\uff0c\u5982\u4f55\u81ea\u5b66</li> <li>\u5982\u4f55\u89c4\u5212\uff1a\u89c4\u5212\u539f\u5219\uff0c80% \u7406\u8bba</li> <li>\u8003\u7814\u6d41\u7a0b\uff1a\u6d41\u7a0b\u7ec6\u5219\uff0c\u7ecf\u9a8c\u5206\u4eab</li> <li>\u5168\u7bc7\u5e45\u65bd\u5de5\u4e2d ing</li> <li>---\u5f85\u66f4\u65b0</li> </ul>"},{"location":"index.html#_3","title":"\u6307\u5357\u610f\u4e49","text":"<p>\u4e00\u4e2a\u6545\u4e8b\u6216\u8bb8\u80fd\u591f\u8bf4\u660e</p> <p>\u8eab\u4e3a\u4e00\u540d\u8ba1\u8f6f\u7684\u65b0\u751f\uff0c\u5c0f\u660e\u3002\u521d\u5165\u6821\u56ed\uff0c\u6000\u7740\u6ee1\u6ee1\u81ea\u559c\uff0c\u53ef\u662f\u6ca1\u6709\u4efb\u4f55\u89c4\u5212\u7684\u4ed6\uff0c\u7b49\u540c\u4e8e\u6ca1\u6709\u4efb\u4f55\u88c5\u5907\u5728\u4e00\u5ea7\u5e9e\u5927\u7684\u8ff7\u5bab\u4e2d\u5bfb\u627e\u51fa\u8def\u3002\u7b2c\u4e00\u5e74\u5306\u5306\u8fc7\u53bb\uff0c\u4ed6\u5f88\u61d2\u60f0\uff0c\u61d2\u5230\u7b2c\u4e00\u5e74\u5bf9\u5404\u79cd\u6821\u56ed\u6d3b\u52a8\uff0c\u793e\u56e2\uff0c\u7ade\u8d5b\uff0c\u61d2\u5230\u8fde\u5357\u9633\u5e02\u533a\u7684\u5730\u65b9\u4e5f\u6ca1\u6709\u53bb\u8fc7\uff0c\u4ed6\u7684\u501f\u53e3\u662f\u6211\u8981\u6b47\u4e00\u6b47\uff0c\u7f13\u89e3\u4e0b\u9ad8\u4e2d\u7684\u82e6\u3002\u968f\u7740\u7b2c\u4e8c\u5e74\u7684\u5230\u6765\uff0c\u4ed6\u7684\u610f\u8bc6\u578b\u6001\u5f00\u59cb\u8f6c\u53d8\uff0c\u4ed6\u6ca1\u6709\u4efb\u4f55\u5728\u6821\u7684\u8d44\u6e90\uff0c\u8fd8\u662f\u5728\u8ff7\u5bab\u4e2d\u6ca1\u6709\u4efb\u4f55\u88c5\u5907\uff0c\u53ea\u662f\u4ed6\u719f\u6089\u4e86\u8ff7\u5bab\u7684\u8def\uff0c\u4f46\u4e00\u76f4\u5728\u4e00\u5b9a\u8303\u56f4\u5185\u539f\u5730\u6253\u8f6c\u3002\u663e\u7136\uff0c\u4ed6\u5f00\u59cb\u884c\u52a8\uff0c\u7531\u4e8e\u662f\u8ba1\u7b97\u673a\u4e13\u4e1a\uff0c\u4ed6\u5e0c\u671b\u52a0\u5165\u793e\u56e2\u6765\u7ba1\u5236\u81ea\u5df1\uff0c\u4e5f\u80fd\u52a8\u624b\u7f16\u8f91\u4ee3\u7801\u3002\u53ef\u662f\uff0c\u5f53\u4ed6\u4ee5\u5927\u4e8c\u7684\u8eab\u4efd\u8fde\u7eed\u8be2\u95ee\u51e0\u4e2a\u793e\u56e2\u540e\uff0c\u6ca1\u4e00\u4e2a\u5e94\u7b54\u3002\u6216\u8bb8\u8d70\u5230\u8fd9\u91cc\uff0c\u4ed6\u5df2\u7ecf\u653e\u5f03\uff0c\u4f46\u610f\u8bc6\u5f62\u6001\u7684\u8f6c\u53d8\u5f7b\u5e95\u6539\u53d8\u7740\u4ed6\uff0c\u8d70\u51fa\u5bbf\u820d\uff0c\u4ed6\u6765\u5230\u4e86\u56fe\u4e66\u9986\uff0c\u5012\u817e\u4e86\u51e0\u5929\u540e\uff0c\u53d1\u73b0\u56fe\u4e66\u9986\u5b58\u5728\u7535\u5b50\u9605\u89c8\u5ba4\uff0c\u4ed6\u4fbf\u9009\u597d\u4f4d\u7f6e\uff0c\u5f00\u59cb\u4e86\u81ea\u8ba4\u4e3a\u6b63\u786e\u7684\u81ea\u5b66\uff0c\u6bcf\u5929\u9664\u4e86\u4e0a\u8bfe\uff0c\u5403\u996d\uff0c\u4ed6\u57fa\u672c\u5f7b\u5e95\u7231\u4e0a\u4e86\u8fd9\u4e2a\u80fd\u591f\u6816\u8eab\u7684\u516c\u5171\u573a\u6240\uff0c\u56e0\u4e3a\uff0c\u6ca1\u6709\u56fe\u4e66\u9986\uff0c\u4ed6\u65e0\u5904\u53ef\u53bb\u3002\u81ea\u5b66\u662f\u56f0\u96be\u7684\uff0c\u5f53\u4ed6\u6253\u5f00 CMU \u7684\u8bfe\u7a0b\u4ed6\u653e\u5f03\u4e86\uff0c\u4f46\u4ed6\u6ca1\u6709\u653e\u5f03\u81ea\u5df1\uff0c\u82b1\u8d39\u4e86 4 \u4e2a\u6708\u540e\uff0c\u4ed6\u52c9\u5f3a\u5543\u4e0b CS61A \u7684\u8bfe\u7a0b\uff0c\u5e76\u6700\u7ec8\u987a\u5229\u5b8c\u6210\u4e86 Scheme project\uff0c\u968f\u7740\u65f6\u95f4\u7684\u63a8\u79fb\uff0c\u4ed6\u5df2\u7ecf\u80fd\u591f\u5728 GitHub \u5bfb\u627e\u5f00\u6e90\u9879\u76ee\uff0cStack overflow \u63d0\u95ee\uff0c\u4f46\u4ed6\u4e5f\u4f1a\u81ea\u95ee\uff0c\u8fd9\u771f\u7684\u6709\u7528\u5417\uff1f\u5728\u8ff7\u5bab\u4e2d\u7684\u5904\u5883\uff0c\u4ed6\u6df1\u523b\u77e5\u9053\u8ff7\u5bab\u4e2d\u8981\u6709\u6307\u5357\u9488\uff0c\u6307\u5411\u6700\u7ec8\u7684\u76ee\u6807\u2014\u2014\u2014\u2014\u5927\u5b66\u56db\u5e74\u6700\u7ec8\u8981\u5e72\u4ec0\u4e48\u3002\u4ed6\u5f00\u59cb\u601d\u8003\uff0c\u6216\u8bb8\u4ed6\u8bfb\u4e86\u8352\u5e9f\u96c6\uff0c\u8bfb\u4e86\u666e\u6797\u65af\u987f\u5fae\u79ef\u5206\uff0c\u8bfb\u4e86\u7f8e\u56fd\u5c11\u513f\u82f1\u8bed\uff0c\u4ed6\u8fd8\u662f\u4e0d\u77e5\u9053\u8981\u5e72\u4ec0\u4e48\uff0c\u4f46\u5e78\u8fd0\u7684\u662f\uff0c\u4ed6\u65e0\u610f\u4e2d\u8bfb\u5230\u4e86\u90d1\u96c5\u541b\u7684\u4e66\u7c4d\uff0c\u5e76\u5f00\u59cb\u601d\u8003\u6700\u7ec8\u7684\u51fa\u8def\uff0c\u5230\u5e95\u4ec0\u4e48\u6837\u7684\u660e\u5929\u662f\u8bbe\u60f3\u7684\uff0c\u4ed6\u89c4\u5212\u7740\uff0c\u5e76\u52aa\u529b\u7740\u2026\u2026\u5982\u679c\u4ed6\u4ece\u521a\u5165\u5b66\u7b2c\u4e00\u5e74\u5c31\u77e5\u9053\u81ea\u5df1\u7684\u6307\u5357\u9488\u6307\u5411\u4f55\u65b9\uff0c\u8ff7\u5bab\u4e2d\u8981\u600e\u4e48\u5bfb\u627e\u81ea\u5df1\u7684\u5b9d\u85cf\uff0c\u6216\u8bb8\u4ed6\u65e9\u4e00\u6b65\u5c31\u80fd\u627e\u5230\u51fa\u53e3\uff0c\u88c5\u5907\u4e5f\u4f1a\u4e0d\u6bd4\u73b0\u5728\u5dee\u3002</p> <p>\u5f88\u591a\u65f6\u5019\uff0c\u6d88\u606f\uff0c\u8d44\u6e90\u7684\u95ed\u585e\u6027\uff0c\u5bf9\u5927\u90e8\u5206\u5927\u5b66\u751f\u6765\u8bf4\uff0c\u8eab\u4e3a\u5177\u6709\u4eab\u7528\u6743\u7684\u8eab\u4efd\uff0c\u4f46\u5374\u4e0d\u80fd\u5f88\u597d\u7684\u4f7f\u7528\uff0c\u6545\u6b64\uff0c\u672c\u6307\u5357\u7684\u610f\u4e49\u5177\u8c61\u5316\u3002</p>"},{"location":"index.html#_4","title":"\u7279\u522b\u9e23\u8c22","text":"<p>\u611f\u8c22\u5df2\u7ecf\u6b65\u5165\u793e\u4f1a\uff0c\u8003\u7814\u4e0a\u5cb8\uff0c\u5b66\u957f\u5b66\u59d0\uff0c\u5404\u540c\u5b66\u7684\u8d21\u732e\uff0c\u6ca1\u6709\u4ed6\u4eec\u7684\u5e2e\u52a9\uff0c\u5c31\u4e0d\u4f1a\u6709 NIT Book\u3002 \u611f\u8c22CS \u81ea\u5b66\u6307\u5357\uff0c\u4e0a\u4ea4\u6307\u5357\u7684\u542f\u53d1\u3002\u4e0a\u4e00\u523b\u7f51\u4e0a\u7684\u53d7\u76ca\u8005\uff0c\u4e0b\u4e00\u523b\u53ef\u4ee5\u662f\u5f00\u6e90\u7684\u53d1\u8d77\u8005\uff01</p>"},{"location":"index.html#_5","title":"\u6b22\u8fce\u4e00\u8d77\u52a0\u5165","text":"<p>\u5982\u6709\u4e0d\u59a5\u6216\u9519\u8bef\uff0c\u8bf7\u53ca\u65f6\u6307\u6b63\uff0c\u53ef\u53f3\u4e0b\u89d2(\u624b\u673a\u7aef\u5de6\u4e0b) Emai \u6216 Github \u7559\u8a00\u3002 \u5982\u6709\u5efa\u8bae\uff0c\u540c\u4e0a\u3002 \u6b22\u8fce Github Pull Request \u4e00\u8d77\u7f16\u5199\u3002</p>"},{"location":"index.html#_6","title":"\u8fd9\u4e2a\u5de5\u7a0b\u662f\u5f88\u96be\u7684\uff0c\u6211\u9080\u8bf7\u4e86\u90e8\u5206\u540c\u5b66\u548c\u5b66\u957f\uff0c\u5f53\u65f6\u7b54\u5e94\u7684\u5f88\u597d\uff0c\u53ef\u662f\u6700\u7ec8\u5374\u6ca1\u6709\u7ed3\u679c","text":"<ul> <li>\u5bf9\u90e8\u5206\u4eba\u795b\u9664\u9b54\u529b\uff0c\u4e00\u4e9b\u4eba\u6ca1\u6709\u4f60\u60f3\u5f97\u90a3\u4e48\u597d\uff0c\u53e3\u5934\u7684\u7b54\u5e94\u4e5f\u4e0d\u7b97\u4ec0\u4e48\u300230\u5c81\u4ee5\u4e0a\u7684\u4eba\u8109\u624d\u7b97\u4eba\u8109\uff0c\u5c41\u5a03\u5a03\u61c2\u5f97\u4e86\u4ec0\u4e48\u3002</li> <li>\u9761\u4e0d\u6709\u521d\uff0c\u9c9c\u523b\u6709\u7ec8\u3002</li> </ul>"},{"location":"%E4%B8%93%E8%AE%BF%E7%AF%87/%E4%BD%93%E8%82%B2%E7%B1%BB.html","title":"\u4f53\u80b2\u961f\u7c7b\u4e13\u8bbf","text":"<p>\u8bbf\u8c08\u662f\u5ba2\u89c2\u7684\uff0c\u771f\u5b9e\u7684\uff0c\u5e0c\u671b\u6b64\u7c7b\u6709\u7528\u4e8e\u4f60\uff0c\u6dcb\u8fc7\u96e8\u6216\u8bb8\u5c31\u60f3\u6491\u4f1e\u3002\u56e0\u4e3a\u7bc7\u5e45\u539f\u56e0\uff0c\u53ea\u622a\u53d6\u90e8\u5206\u3002</p>"},{"location":"%E4%B8%93%E8%AE%BF%E7%AF%87/%E4%BD%93%E8%82%B2%E7%B1%BB.html#_2","title":"\u6821\u7bee\u7403\u961f\u8bbf\u8c08","text":"<p>22 LHJ\uff1a</p> <ul> <li>Liu\uff1a\u4e3a\u4ec0\u4e48\u9009\u62e9\u7bee\u7403\u961f\uff1f</li> <li>Li\uff1a\u6211\u9009\u62e9\u52a0\u5165\u7bee\u7403\u961f\uff0c\u4e3b\u8981\u56e0\u4e3a\u5bf9\u7bee\u7403\u7684\u70ed\u7231\uff0c\u6211\u89c9\u5f97\u7bee\u7403\u662f\u4e00\u9879\u7ade\u6280\u8fd0\u52a8\uff0c\u559c\u6b22\u7bee\u7403\u5c31\u662f\u5bf9\u8fd9\u79cd\u7ade\u6280\u7684\u70ed\u7231\u3002\u5176\u6b21\u5c31\u662f\u5e0c\u671b\u901a\u8fc7\u56e2\u961f\u8fd0\u52a8\u953b\u70bc\u81ea\u5df1\u7684\u56e2\u961f\u534f\u4f5c\u80fd\u529b\u3002\u6700\u540e\u5728\u5e0c\u671b\u901a\u8fc7\u8bad\u7ec3\u5728\u6bd4\u8d5b\u4e2d\u5c55\u73b0\u5728\u81ea\u5df1\uff0c\u8fd9\u80fd\u7ed9\u6211\u4e0d\u4ec5\u4ec5\u662f\u751f\u6d3b\u4e2d\u5b66\u4e60\u4e2d\u7684\u5f88\u591a\u81ea\u4fe1\u3002</li> <li>Liu: \u66f4\u591a\u7684\u662f\u70ed\u7231\uff0c\u4ec0\u4e48\u4e8b\u60c5\u90fd\u8981\u6709\u5174\u8da3\u3002\u5bf9\u8eab\u5fc3\u4e0a\u7684\u5b9e\u9645\u611f\u53d7\u6536\u76ca\u5982\u4f55\uff1f</li> <li>Li\uff1a\u7bee\u7403\u9996\u5148\u6709\u52a9\u4e8e\u63d0\u9ad8\u8eab\u4f53\u7d20\u8d28\uff0c\u589e\u5f3a\u5fc3\u80ba\u529f\u80fd\uff0c\u63d0\u9ad8\u65b0\u9648\u4ee3\u8c22\uff0c\u5bf9\u6211\u4eec\u7684\u5065\u5eb7\u6709\u5f88\u5927\u7684\u5e2e\u52a9\u540c\u65f6\u4e5f\u53ef\u4ee5\u57f9\u517b\u575a\u97e7\u4e0d\u62d4\u3001\u6c38\u4e0d\u653e\u5f03\u7684\u7cbe\u795e\u54c1\u8d28\u3002\u7bee\u7403\u4e5f\u6709\u52a9\u4e8e\u91ca\u653e\u538b\u529b\uff0c\u5728\u4f60\u5fc3\u60c5\u4e0d\u597d\u7684\u65f6\u5019\uff0c\u53ef\u4ee5\u81ea\u5df1\u53bb\u6253\u6253\u7bee\u7403\uff0c\u7bee\u7403\u4e0d\u4f1a\u8bf4\u8bdd\uff0c\u4eab\u53d7\u8fd9\u79cd\u6c89\u6d78\u7684\u65f6\u523b\u4f1a\u8ba9\u81ea\u5df1\u7684\u8eab\u5fc3\u5f97\u5230\u653e\u677e\u3002\u7bee\u7403\u540c\u65f6\u4e5f\u53ef\u4ee5\u7ed3\u8bc6\u5fd7\u540c\u9053\u5408\u7684\u670b\u53cb\uff0c\u7bee\u7403\u8ba9\u6211\u4eec\u805a\u5728\u4e00\u8d77\uff0c\u540c\u65f6\u4e5f\u80fd\u6269\u5927\u81ea\u5df1\u7684\u4eba\u8109\u5173\u7cfb\u3002\u7f3a\u70b9\u5c31\u662f\u8bad\u7ec3\u548c\u6bd4\u8d5b\u9700\u8981\u82b1\u8d39\u65f6\u95f4\u6bd4\u8f83\u591a\uff0c\u53ef\u80fd\u5f71\u54cd\u5b66\u4e1a\u548c\u5176\u4ed6\u6d3b\u52a8\u3002\u4f46\u662f\uff0c\u7bee\u7403\u8fd0\u52a8\u4e2d\u7684\u56e2\u961f\u534f\u4f5c\u3001\u6c9f\u901a\u80fd\u529b\u5f88\u91cd\u8981\uff0c\u5728\u6bd4\u8d5b\u4e2d\u9700\u8981\u79ef\u6781\u548c\u961f\u53cb\u6c9f\u901a\uff0c\u6bd4\u5982\u9632\u5b88\u65b9\u9762\u7684\u95ee\u9898\u7b49\u3002\u5176\u4e2d\u7bee\u7403\u5e26\u7ed9\u6211\u4e0d\u653e\u5f03\u575a\u6301\u4e0d\u61c8\u7684\u7cbe\u795e\u662f\u65e0\u4ef7\u7684\u3002</li> <li>Liu\uff1a\u8eab\u4f53\u662f\u9769\u547d\u7684\u672c\u94b1\uff0c\u5065\u5eb7\u5f88\u91cd\u8981\uff0c\u6709\u65f6\u9700\u8981\u6743\u8861\u4e0b\u5b66\u4e60\u548c\u5065\u5eb7\u7684\u4f4d\u7f6e\u3002\u7bee\u7403\u961f\u7684\u5173\u6ce8\u5ea6\u5f88\u9ad8\uff0c\u6bcf\u6b21\u4f60\u4eec\u6bd4\u8d5b\u5c31\u4f1a\u6709\u5f88\u591a\u4eba\u56f4\u89c2\uff0c\u90a3\u4e48\u961f\u5185\u7684\u6bd4\u8d5b\u5b9e\u9645\u5956\u52b1\u6709\u4ec0\u4e48\uff1f</li> <li>Li\uff1a\u7bee\u7403\u6bd4\u8d5b\u6709\u673a\u4f1a\u83b7\u5f97\u5956\u676f\u3001\u8363\u8a89\u7b49\u7269\u8d28\u548c\u7cbe\u795e\u5956\u52b1\u3002</li> <li>Liu\uff1a\u4f53\u80b2\u7c7b\u7ade\u8d5b\u5bf9\u7efc\u6d4b\u52a0\u5206\u4e5f\u662f\u9644\u52a0\u7684\u76ca\u5904\uff0c\u90a3\u4e48\u5982\u679c\u518d\u9009\u4e00\u6b21\uff0c\u4f60\u8fd8\u4f1a\u53c2\u52a0\u5417\uff1f</li> <li>Li\uff1a\u4f1a\uff0c\u5982\u679c\u6211\u5bf9\u7bee\u7403\u7684\u70ed\u7231\u4f9d\u7136\u5982\u521d\uff0c\u6211\u4f1a\u9009\u62e9\u7ee7\u7eed\u52a0\u5165\u7bee\u7403\u961f\u3002\u56e0\u4e3a\u5728\u7bee\u7403\u961f\u7684\u7ecf\u5386\u8ba9\u6211\u6536\u83b7\u4e86\u6210\u957f\u3001\u53cb\u8c0a\u548c\u96be\u5fd8\u7684\u56de\u5fc6\uff0c\u548c\u65e0\u6cd5\u7528\u91d1\u94b1\u8861\u91cf\u7684\u575a\u6301\u7cbe\u795e\u3002\u7bee\u7403\u5e26\u7ed9\u6211\u4e86\u5f88\u591a\uff01</li> <li>Liu\uff1a\u55ef\uff0c\u53cb\u8c0a\u548c\u6210\u957f\u6211\u60f3\u6bd4\u65e0\u610f\u4e49\u7684\u5185\u5377\u663e\u5f97\u66f4\u6709\u4ef7\u503c\u3002</li> </ul> <p>\u7b80\u5355\u6765\u8bf4\uff1a\u8fdb\u4f53\u80b2\u7c7b\u793e\u56e2\uff0c\u5bf9\u8eab\u5fc3\u65b9\u9762\u6709\u76ca\uff0c\u4f46\u5bf9\u672c\u4e13\u4e1a\u5b66\u4e60\uff0c\u5c24\u5176\u662f\u7406\u5de5\u79d1\u7c7b\uff0c\u751a\u662f\u4e0d\u53cb\u597d\u3002However\uff0cyou can make more friends of the opposite sex.</p>"},{"location":"%E5%85%B3%E4%BA%8E%E7%A4%BE%E5%9B%A2/%E6%96%BD%E5%B7%A5ing.html","title":"\u65bd\u5de5ing","text":""},{"location":"%E5%85%B3%E4%BA%8E%E8%AF%BE%E5%A0%82/%E6%96%BD%E5%B7%A5ing.html","title":"\u65bd\u5de5ing","text":""},{"location":"%E5%8A%A0%E5%B7%A5%E5%8C%BA/c.html","title":"\u5173\u4e8e C/CPP \u7684\u5165\u95e8\u5b66\u4e60\u8def\u7ebf\u5efa\u8bae","text":"<p>How to learn it?</p> <ol> <li>\u60f3\u5b66\u597d\uff0c\u82f1\u8bed\u8981\u5230\u4f4d\uff01\u9759\u5fc3\u8bfb\u82f1\u6587\u6587\u6863\uff0c\u4e0d\u4f1a\u7684\u8bcd\u7ffb\u8bd1\uff0c\u89c1\u7684\u591a\u4e86\uff0c\u4e0d\u7528\u7279\u522b\u8bb0\u5fc6\u5c31\u80fd\u8bb0\u4f4f\u5355\u8bcd\uff0c\u82f1\u8bed\u7684\u91cd\u8981\u6027\u4e0d\u5728\u8d58\u8ff0\u3002</li> <li>\u901a\u8fc7<code>C/CPP</code>\u5b66\u4e60\u6570\u636e\u7ed3\u6784</li> <li><code>QT</code>\u9879\u76ee</li> <li>\u7b97\u6cd5\u7ade\u8d5b</li> <li>\u7535\u5b50\u4e66</li> </ol>"},{"location":"%E5%8A%A0%E5%B7%A5%E5%8C%BA/c.html#ccpp_1","title":"\u5165\u95e8 C/CPP\uff1a","text":"<p>\u5efa\u8bae\uff1a\u6bcf\u5929\u5b66\u4e00\u8282\u5373\u53ef</p> <ul> <li>CS106L <p>\u5feb\u901f\u5165\u95e8\u8bfe\u7a0b\uff08\u6838\u5fc3\u51fa\u88c5\u82f1\u8bed\uff0c\u8ddf\u7740PPT\u901f\u62101\u5468\u5373\u53ef\uff09 \u53ef\u4ee5\u53c2\u8003\u6211\u7684\u5b66\u4e60\u7b14\u8bb0</p> </li> <li>codecademy <ul> <li>\u5728\u7ebf\u5b9e\u64cd<code>C/CPP</code>\uff0c\u901a\u8fc7<code>g++</code>\u7f16\u8f91</li> <li>\u6709<code>AI</code>\u8f85\u52a9</li> <li>ps\uff1a\u505a\u5230\u540e\u9762\u53d1\u73b0\u4ed8\u8d39\uff01\uff01\u4f46\u662f 0 \u57fa\u7840\u767d\u5ad6\u524d\u51e0\u4e2a\u8fd8\u662f\u63a8\u8350, 2\u5c0f\u65f6\u5b8c\u6210\u3002</li> </ul> </li> <li>CS50X <ul> <li>\u54c8\u4f5b\u516c\u5f00\u8bfe\uff0c\u7f51\u7ad9\u6709\u8be6\u7ec6\u6587\u6863\uff0c\u6559\u4f60\u5982\u4f55\u81ea\u5b66\u8fd9\u95e8\u8bfe\u7a0b</li> <li>\u7531\u6d45\u5165\u6df1\uff0c\u751a\u81f3\u642d\u5efa\u4e2a\u4eba\u7f51\u9875\uff08Flsak\uff09 </li> </ul> </li> <li>geeksforgeeks <ul> <li>\u8be6\u7ec6\u6570\u636e\u7ed3\u6784\u6559\u7a0b\u6587\u6863</li> </ul> </li> <li>usfac <ul> <li>\u6570\u636e\u7ed3\u6784\u53ef\u89c6\u5316\u7f51\u7ad9\uff0c\u5e2e\u52a9\u4f60\u66f4\u6e05\u6670\u7684\u4e86\u89e3\u6570\u636e\u7ed3\u6784</li> </ul> </li> <li>C-learn <ul> <li>\u901f\u6210\u8bed\u6cd5\u6587\u6863\uff0c\u5e7f\u544a\u8f83\u591a\uff0c\u503c\u5f97\u6ce8\u610f\u7684\u662f\u7f51\u7ad9\u662f<code>Flask</code>\u6846\u67b6\u642d\u5efa</li> </ul> </li> <li>W3C <ul> <li>\u901f\u6210\u8bed\u6cd5\uff0c\u800c\u4e14\u6709\u4e2a\u4eba\u535a\u5ba2\u7a7a\u95f4\uff08\u5b50\u57df\u540d\uff09\uff0c\u53ea\u8981\u4f1a<code>Html\u3001Css\u3001JS</code>\u5373\u53ef\u4f53\u9a8c\u8bbe\u8ba1\u7f51\u7ad9</li> </ul> </li> </ul> <p>\u5165\u95e8\u540e\uff0c\u57fa\u672c\u4e86\u89e3<code>C/CPP</code>\u6570\u636e\u7ed3\u6784</p>"},{"location":"%E5%8A%A0%E5%B7%A5%E5%8C%BA/c.html#_1","title":"\u7b97\u6cd5\u7ade\u8d5b","text":"<p>Online \u5728\u7ebf\u6bd4\u8d5b</p> <ul> <li>Codeforce <ul> <li>\u5168\u7403\u6700\u5927\u7684\u7b97\u6cd5\u7ade\u8d5b\u7f51\u7ad9\uff0c\u9898\u76ee\u82f1\u6587\uff0c\u6bcf\u573a\u6bd4\u8d5b\u53ef\u4ee5 VP\uff0c\u9002\u5408\u7ec3\u4e60\u6570\u636e\u7ed3\u6784\u4e0e\u7b97\u6cd5\uff0c\u6bcf\u573a\u6bd4\u8d5b\u6709\u9898\u89e3\uff0c\u80fd\u591f\u770b\u5927\u795e\u4ee3\u7801</li> </ul> </li> <li>Atcoder <ul> <li>\u540c\u4e0a\uff0c\u53ea\u4e0d\u8fc7\u662f\u65e5\u672c\u7684\u7f51\u7ad9\uff0c\u6709\u89c6\u9891\u8bb2\u89e3</li> </ul> </li> <li>CSES <ul> <li>\u8be6\u7ec6\u9898\u5355\u7ec3\u4e60</li> </ul> </li> <li>\u6570\u5b66\u7c7b\u7f16\u7a0b\u95ee\u9898 <ul> <li>\u504f\u91cd\u6570\u5b66\u9898\u76ee</li> </ul> </li> </ul> <p>\u4ee5\u4e0a\u662f\u82f1\u6587\uff0c\u4ee5\u4e0b\u662f\u4e2d\u6587\uff0c\u56fd\u5185\u76f4\u63a5\u641c\u7d22\u5373\u53ef</p> <ul> <li>\u6d1b\u8c37 <ul> <li>\u65b0\u4eba\u5fc5\u5907\uff0c\u5237\u5b8c\u5b98\u65b9\u57fa\u7840\u9898\u5355\u5417\uff0c\u7bee\u7403\u676f\u8d77\u7801\u56fd\u4e09</li> </ul> </li> <li>LeetCode <ul> <li>\u867d\u7136\u597d\uff0c\u4f46\u662f\u4e0d\u5efa\u8bae\u6ca1\u5b66\u4f1a\u7c7b\u4e2d\u89e3\u51b3\u95ee\u9898\u7684\u4eba\u5b66</li> <li>\u6bcf\u5468\u6bd4\u8d5b 4 \u9898\uff0c\u6392\u540d\u6709\u5956\u52b1</li> </ul> </li> <li>\u6398\u91d1\u793e\u533a oj <ul> <li>\u8c46\u5305 AI \u8f85\u52a9\uff0c\u76f4\u63a5\u7ed9\u51fa\u5b8c\u5168\u7684\u6d4b\u8bd5\u89e3\u51b3\u4ee3\u7801</li> <li>\u6709\u5b57\u8282\u9752\u8bad\u6d3b\u52a8\uff0c\u6691\u671f\u9879\u76ee</li> </ul> </li> <li>\u725b\u5ba2 <ul> <li>\u6709\u7ade\u8d5b\u4e13\u533a\uff0c\u53ef\u4ee5\u6253\u6bd4\u8d5b\uff0c\u7ec3\u4e60\u9898\u76ee</li> <li>\u5bd2\u5047\uff0c\u6691\u5047\u6709\u7b97\u6cd5\u57f9\u8bad\u73ed\uff0c\u4ea4\u94b1</li> </ul> </li> </ul> <p>ps\uff1a\u719f\u6089\u8fd9\u4e9b\uff0c\u5982\u679c\u4f60\u662f\u6563\u4fee\uff08\u65e0 ACM\uff0c\u65e0\u793e\u56e2\uff09\uff0c\u4e5f\u80fd\u591f\u6c34\u4e00\u4e9b\u7f16\u7a0b\u7f16\u7a0b\u6bd4\u8d5b\u62ff\u5956</p>"},{"location":"%E5%8A%A0%E5%B7%A5%E5%8C%BA/c.html#qt","title":"<code>QT</code>\u9879\u76ee","text":"<p>\u9879\u76ee\u7684\u91cd\u8981\u6027\uff0c\u6216\u8bb8\u53ea\u7528\u5199\u7b80\u5386\u624d\u77e5\u9053\uff0c\u5b66\u751f\u7ba1\u7406\u7cfb\u7edf\u6839\u672c\u4e0d\u53eb\u9879\u76ee\uff01\uff01\uff01</p> <ul> <li>QT \u9879\u76ee <ul> <li>b \u7ad9\u641c\uff0cGoogle \u76f4\u641c\uff0cytb \u76f4\u641c</li> <li><code>Cs\u81ea\u5b66\u6307\u5357\u4e2d\u7684C/CPP\u8bfe\u7a0b\u4e2d\u5305\u542b\u4e86Qt\u9879\u76ee</code></li> </ul> </li> </ul> <p>\u8fd8\u6709 Socket\u3001\u6e38\u620f\u9879\u76ee\uff0c\u4e0d\u63a8\u8350\u5b66\u4e60\uff0c\u56e0\u4e3a\u76ee\u524d\u624d\u5b66\u4e86\u8fd9\u4e48\u70b9\uff0c\u8ddf\u505a QT \u5373\u53ef</p>"},{"location":"%E5%8A%A0%E5%B7%A5%E5%8C%BA/c.html#_2","title":"\u8865\u5145\u8bf4\u660e","text":"<ul> <li>\u7ef4\u57fa\u767e\u79d1 \u8f85\u52a9\u5b9a\u4e49</li> <li>Chatgpt \u8f85\u52a9\u5b66\u4e60</li> <li>\u8bfe\u7a0b\u4ea4\u6d41\u7fa4\u8f85\u52a9\u5b66\u4e60\uff0c\u4f46\u4e0d\u8981\u603b\u662f\u6c34\u7fa4</li> <li>\u5fae\u4fe1\u8bfb\u4e66 APP\uff08or Z-lib\uff09</li> <li>CSdiy \u81ea\u5b66\u7f51\u7ad9\u4e2d\u7684\u5176\u4ed6 C/CPP \u8bfe\u7a0b\u4e0d\u5728\u8d58\u8ff0</li> <li>\u6709\u65f6\u95f4\u7ecf\u5386\u5efa\u8bae\u8ddf\u7740 CS \u8bfe\u7a0b\u5b66\u4e60\uff01\uff01\uff01 ps:Steam\u4e0a\u514d\u8d39\u7684\u300a\u6570\u636e\u7ed3\u6784\u300b\u6e38\u620f\u53ef\u4ee5\u5f53\u4f5c\u6d88\u9063\uff0c\u52a0\u6df1\u5370\u8c61 \u5efa\u8bae\u5b66\u4e60\u5199\u535a\u5ba2\uff0c\u5e76\u6301\u4e45\u7684\u5199\uff0c\u8d39\u66fc\u5b66\u4e60\u6cd5\uff01</li> </ul>"},{"location":"%E5%8A%A0%E5%B7%A5%E5%8C%BA/c.html#_3","title":"\u8865\u5145","text":"<ul> <li>\u5982\u679c\u66f4\u597d\u5173\u4e8e<code>C/CPP</code>\u7684\u5efa\u8bae\uff0c\u6b22\u8fce\u8865\u5145\u3002</li> <li>PR or Emil me\uff1a2633699957@qq.com</li> </ul>"},{"location":"%E5%8A%A0%E5%B7%A5%E5%8C%BA/xxx.html","title":"x","text":""},{"location":"%E5%8A%A0%E5%B7%A5%E5%8C%BA/xxx.html#_1","title":"\u901f\u901a\u671f\u672b\u8003\u8bd5","text":"<p>1.\u5224\u65ad\u81ea\u5df1\u662f\u5426\u6709\u57fa\u7840</p> <ul> <li>\u6709\uff0c\u5219\u505a\u76f8\u5e94\u4e60\u9898\uff0c\u5f80\u5c4a\u8d44\u6599\uff0c\u5b66\u4e60\u901a\u4e60\u9898\uff0cb \u7ad9\u76f4\u641c\u3002\u5982\u8fd9\u4e9b\u505a\u5b8c\u4e0d\u653e\u5fc3\uff0c\u5219\u5237\u4e00\u904d\u901f\u6210\u8bfe\u5373\u53ef</li> <li>\u65e0\uff0c\u5148\u901f\u6210\u8bfe\uff0c\u5728\u4e60\u9898</li> </ul> <p>ps:\u4e00\u4e2a\u5bbf\u820d\u5982\u679c\u6ca1\u6709\u5206\u4eab\u8d44\u6599\u7684\u884c\u4e3a\uff0c\u559c\u6b22\u5efa\u7acb\u5c0f\u56e2\u4f53\uff0c\u90a3\u4e48\u5230\u793e\u4f1a\u4e0a\u9047\u5230\u771f\u91d1\u767d\u94f6\u7684\u95ee\u9898\uff0c\u4f60\u4f1a\u76f8\u4fe1\u4e00\u4e2a\u671f\u672b\u8d44\u6599\u90fd\u4e0d\u5206\u4eab\u7684\u4eba\u7ed9\u4f60\u5e2e\u52a9\u5417\uff1f \u4f46\u662f\u4e0d\u5fc5\u62c5\u5fc3\uff0c\u8fd9\u4e9b\u8d44\u6599\u53ef\u4ee5\u95ee\u95ee\u5176\u4ed6\u5bbf\u820d\u7684\u4eba\uff0c\u8d44\u6599\u53c8\u4e0d\u662f\u638c\u63e1\u5728\u5c11\u6570\u4eba\u624b\u4e2d\u3002</p> <p>2.\u5173\u4e8e\u4f5c\u5f0a</p> <ul> <li>\u4f60\u6216\u8bb8\u4f1a\u77e5\u9053\u6709\u4e9b\u4eba\u901a\u8fc7\u4f5c\u5f0a\u62ff\u5230\u9ad8\u5206\uff0c\u901a\u8fc7\u6c34\u8d5b\u62ff\u5230\u5956\u5b66\u91d1\uff0c\u4f60\u4f1a\u600e\u4e48\u529e\uff1f\u5927\u591a\u6570\u4eba\u9009\u62e9\u8499\u773c\u8fc7\u53bb\uff0c\u4f46\u662f\u4f60\u4ed4\u7ec6\u7684\u5ba1\u67e5\uff0c\u4ed6/\u5979\u5728\u635f\u5bb3\u4f60\u7684\u5229\u76ca\uff0c\u8ba9\u4f60\u672c\u80fd\u591f\u5f97\u5230\u4e00\u7b49\u5956\u5b66\u91d1\uff0c\u4f46\u662f\u6700\u7ec8\u5374\u662f\u4e8c\u7b49\u5956\u5b66\u91d1\uff0c\u4f60\u7518\u5fc3\u5417\uff1f</li> </ul> <p>\u5f53\u7136\uff0c\u5982\u679c\u4f60\u662f\u6ca1\u6709\u8fd9\u79cd\u624b\u6bb5\u8fc7\u4e0d\u53bb\uff0c\u7948\u6c42\u53ca\u683c\u5206\u6570\u5373\u53ef\uff0c\u81ea\u5df1\u5ba1\u89c6\u5ea6\u91cf</p> <p>ps:\u5728\u4e8c\u672c\u5b66\u9662\u62ff\u5956\u5b66\u91d1\u8fd9\u79cd\u4e8b\u60c5\u4e0d\u5982\u770b\u5341\u672c\u4e66\u6765\u7684\u4ef7\u503c\u66f4\u9ad8\uff0c\u4f46\u662f\u5546\u4e1a\u5316\u4e2a\u4eba\u4ef7\u503c\u7684\u4eca\u5929\uff0c\u5982\u4f55\u53d6\u820d\u4f3c\u4e4e\u5546\u4e1a\u5316\u5b8c\u80dc\uff01</p>"},{"location":"%E5%8A%A0%E5%B7%A5%E5%8C%BA/xxx.html#_2","title":"\u5173\u4e8e\u901f\u6210","text":"<p>1.\u9ad8\u65af\u8bfe\u5802 or \u7334\u535a\u58eb \u7b49\u4e00\u7cfb\u5217\u901f\u6210\u8bfe\u3002</p> <ul> <li>\u5982\u5b9e\u5728\u627e\u4e0d\u5230\uff0c\u67d0\u5b9d\u3001\u67d0\u591a\u4e70\u4e2a\u5373\u53ef\uff0c\u51e0\u5757\u94b1\u7684\u529f\u592b</li> </ul> <p>2.\u6700\u91cd\u8981\u7684\u4f9d\u65e7\u662f\u8001\u5e08\u5212\u7684\u9898\u76ee\u8303\u56f4</p> <ul> <li>\u8001\u5e08\u5212\u7684\u9898\u76ee\u8303\u56f4\u662f\u6700\u91cd\u8981\u7684</li> </ul> <p>ps:\u8ba4\u771f\u590d\u4e60\uff0c\u5343\u4e07\u522b\u9a9a\u770b\u522b\u4eba\uff0c\u505a\u597d\u81ea\u5df1\u7684\u4e8b\u60c5</p>"},{"location":"%E5%8A%A0%E5%B7%A5%E5%8C%BA/%E5%AF%92%E6%9A%91%E5%81%87%E5%BB%BA%E8%AE%AE.html","title":"\u5bd2\u6691\u5047\u7559\u6821\u5b66\u4e60\u7684\u5efa\u8bae","text":"<p>\u5173\u4e8e\u6691\u5047\u7559\u6821\uff0c\u8d77\u521d\u662f\u542c\u5230\u67d0\u9662\u8d1f\u8d23\u4eba\u8c08\u8d77\u8ba9\u4ed6\u513f\u5b50\u7559\u6821\u7684\u4e8b\u60c5\uff0c\u6211\u624d\u8ba4\u8bc6\u5230\uff0c\u5728\u6691\u5047\u7559\u6821\u7684\u91cd\u8981\u6027\u3002\u6700\u91cd\u8981\u7684\u662f\u5b66\u66f4\u591a\u7684\u8bfe\u7a0b\uff01</p>"},{"location":"%E5%8A%A0%E5%B7%A5%E5%8C%BA/%E5%AF%92%E6%9A%91%E5%81%87%E5%BB%BA%E8%AE%AE.html#_2","title":"\u5b66\u66f4\u591a\u7684\u8bfe\u7a0b","text":"<ul> <li>\u6691\u671f\u7559\u6821\uff0c\u6709\u65f6\u95f4\u5f00\u66f4\u591a\u7684CS\u8bfe\u7a0b\uff0c\u4e5f\u53ef\u4ee5\u66f4\u52a0\u7cfb\u7edf\u7684\u5b66\u4e60\u67d0\u65b9\u9762\u7684\u77e5\u8bc6\u6216\u8005\u9884\u4e60\u67d0\u65b9\u9762\u7684\u77e5\u8bc6\uff0c\u4f8b\u5982\uff1a\u9ad8\u6570\u3001\u7ebf\u4ee3\u3001\u79bb\u6563\u3001\u82f1\u8bed4\u30016\u7ea7\u3001Java\u9879\u76ee\u3001go/golang\u9879\u76ee ... \u6709\u793e\u56e2\u5b9e\u9a8c\u5ba4\u7684\u7559\u6821\u76ee\u7684\u662f\u4e3a\u6bd4\u8d5b\u3001\u8001\u5e08\u7684\u9879\u76ee\u8d44\u6e90\u4e0a\u4e0b\u529f\u592b\u3002\u5982\u679c\u662f\u6563\u4fee\uff0c\u4f60\u7684\u5e78\u8fd0\u70b9\u662f\u53ef\u4ee5\u5b66\u81ea\u5df1\u611f\u5174\u8da3\u7684\uff0c\u4f46\u5207\u8bb0\u5b66\u4e60\u7684\u5bfc\u5411\u8981\u7b26\u5408\u5546\u4e1a\u5316\u7684\u793e\u4f1a\uff01\u6211\u4eec\u76ee\u524d\u8fd8\u4e0d\u80fd\u771f\u6b63\u7684\u6563\u4fee\uff01</li> </ul>"},{"location":"%E5%8A%A0%E5%B7%A5%E5%8C%BA/%E5%AF%92%E6%9A%91%E5%81%87%E5%BB%BA%E8%AE%AE.html#_3","title":"\u81ea\u63a7\u529b\u65b9\u9762","text":"<ul> <li>\u7559\u6821\u5b66\u4e60\u53ef\u4ee5\u5e2e\u52a9\u4f60\u57f9\u517b\u66f4\u5f3a\u7684\u81ea\u63a7\u529b\u3002\u5728\u5b66\u6821\u7684\u73af\u5883\u4e2d\uff0c\u4f60\u53ef\u4ee5\u66f4\u5bb9\u6613\u5730\u5236\u5b9a\u548c\u9075\u5b88\u5b66\u4e60\u8ba1\u5212\uff0c\u907f\u514d\u5728\u5bb6\u4e2d\u53ef\u80fd\u9047\u5230\u7684\u5404\u79cd\u5e72\u6270\u3002</li> </ul>"},{"location":"%E5%8A%A0%E5%B7%A5%E5%8C%BA/%E5%AF%92%E6%9A%91%E5%81%87%E5%BB%BA%E8%AE%AE.html#_4","title":"\u751f\u6d3b\u9002\u5e94\u65b9\u9762","text":"<ul> <li>\u7559\u6821\u671f\u95f4\uff0c\u72ec\u7acb\u751f\u6d3b\u3002\u4f60\u9700\u8981\u81ea\u5df1\u5b89\u6392\u996e\u98df\u3001\u4f5c\u606f\u548c\u5b66\u4e60\u65f6\u95f4\uff0c\u8fd9\u6709\u52a9\u4e8e\u63d0\u9ad8\u751f\u6d3b\u81ea\u7406\u80fd\u529b\u548c\u65f6\u95f4\u7ba1\u7406\u80fd\u529b\u3002</li> </ul>"},{"location":"%E5%8A%A0%E5%B7%A5%E5%8C%BA/%E5%AF%92%E6%9A%91%E5%81%87%E5%BB%BA%E8%AE%AE.html#_5","title":"\u771f\u6b63\u7684\u4e0a\u8fdb","text":"<ul> <li>\u5728\u5b66\u6821\u7684\u5b66\u4e60\u6c1b\u56f4\u4e2d\uff0c\u4f60\u53ef\u4ee5\u66f4\u4e13\u6ce8\u4e8e\u5b66\u4e1a\uff0c\u907f\u514d\u5728\u5bb6\u4e2d\u53ef\u80fd\u51fa\u73b0\u7684\u61d2\u6563\u548c\u62d6\u5ef6\u3002</li> </ul>"},{"location":"%E5%8A%A0%E5%B7%A5%E5%8C%BA/%E5%AF%92%E6%9A%91%E5%81%87%E5%BB%BA%E8%AE%AE.html#_6","title":"\u5fc5\u987b\u7559\u6821\u7684\u60c5\u51b5","text":"<ul> <li>\u8003\u8651\u5230\u4e8c\u672c\u5b66\u751f\u7684\u5dee\u5f02\u578b\uff0c\u5982\u679c\u8981\u81ea\u5b66\u8003\u7814\uff0c\u5219\u7559\u6821\u662f\u4f60\u7684100%\u9009\u62e9\uff0c\u56fe\u4e66\u9986\u4e0d\u5f00\u65b9\uff0c\u79df\u4e2a\u81ea\u4e60\u5ba4\uff0c\u6216\u5728\u5bbf\u820d\u5b66\u4e60\u3002</li> <li>\u96c5\u601d\u6258\u798f\u4e0d\u592a\u6e05\u695a\uff0c\u5982\u679c\u4e3a\u4e86\u7533\u8bf7\u56fd\u5916\u7814\u7a76\u751f\u7684\u8bdd\uff0c\u81f3\u5c11\u89816.0\u4ee5\u4e0a\uff0cGPA3.0\u4ee5\u4e0a\uff0c\u81ea\u5b66\u7684\u8bdd\u8fd8\u662f\u5efa\u8bae\u7559\u6821\uff0c\u9664\u62a5\u76f8\u5173\u673a\u6784\u3002</li> </ul> <p>\u5bd2\u5047\u56e0\u4e3a\u8981\u8fc7\u5e74\u56de\u5bb6\uff0c\u8fd9\u65f6\u5019\u53ef\u4ee5\u590d\u73b0\u4f60\u7684\u953b\u70bc\u6210\u8fc7\uff0c\u5728\u4e0d\u4e0a\u5fc3\uff0c\u6d51\u6d51\u5669\u5669\u7684\u8bdd\uff0c\u5c31\u5c11\u70b9\u81ea\u8d23\uff0c\u591a\u4e9b\u5e73\u6de1\u5fc3\uff0c\u4e0d\u8981\u6709\u90a3\u4e48\u591a\u9ad8\u7684\u8ffd\u6c42\u3002</p>"},{"location":"%E5%A6%82%E4%BD%95%E8%A7%84%E5%88%92/%E6%96%BD%E5%B7%A5ing.html","title":"\u65bd\u5de5ing","text":""},{"location":"%E6%96%B0%E7%9A%84%E4%BD%93%E7%B3%BB/%E7%8F%AD%E7%BA%A7%E8%81%8C%E4%BD%8D%E4%BC%98%E7%BC%BA%E5%88%86%E6%9E%90.html","title":"\u65bd\u5de5ing","text":""},{"location":"%E6%A0%A1%E5%9B%AD%E7%94%9F%E6%B4%BB/%E5%88%9D%E5%85%A5%E6%A0%A1%E5%9B%AD.html","title":"\u521d\u5165\u6821\u56ed","text":""},{"location":"%E6%A0%A1%E5%9B%AD%E7%94%9F%E6%B4%BB/%E5%88%9D%E5%85%A5%E6%A0%A1%E5%9B%AD.html#_1","title":"\u521d\u5165\u6821\u56ed","text":"<p>\u77e5\u4ee5\u5f80\u4e4b\u4e0d\u8c0f\uff0c\u77e5\u6765\u8005\u4e4b\u53ef\u8ffd</p> <p>\u4ec5\u51ed\u611f\u89c9\u7684\u9009\u62e9\u4e86\u77ed\u77ed\u51e0\u5b57\u7684\u4e13\u4e1a\uff0c\u6765\u5230\u7684\u65b0\u7684\u6821\u56ed\uff0c\u73b0\u5b9e\u7684\u843d\u5dee\u6216\u8bb8\u5f88\u5927\uff0c\u548c\u81ea\u5df1\u7684\u611f\u89c9\u76f8\u5dee\u751a\u8fdc\u3002\u65e2\u7136\u65e0\u6cd5\u6539\u53d8\uff0c\u90a3\u4e48\u6362\u4e2a\u65b9\u6cd5\uff0c\u5f00\u59cb\u65b0\u6821\u56ed\u4e4b\u65c5\u3002</p>"},{"location":"%E6%A0%A1%E5%9B%AD%E7%94%9F%E6%B4%BB/%E5%88%9D%E5%85%A5%E6%A0%A1%E5%9B%AD.html#_2","title":"\u4e86\u89e3\u4f60\u5373\u5c06\u751f\u6d3b\u56db\u5e74\u7684\u73af\u5883","text":"<p>\u521d\u5165\u6821\u56ed\uff0c\u6821\u56ed\u5927\u81f4\u5206\u897f\u5317\uff0c\u4e1c\u5357\uff0c\u4e1c\u6821\u533a\u3002</p> <p>\u521a\u5165\u6821\u56ed\uff0c\u5e94\u719f\u6089\u73af\u5883\uff0c\u4ece\u5bbf\u820d\u8d70\u51fa\uff0c\u9664\u4e86\u6559\u5b66\u697c\u548c\u98df\u5802\u4e4b\u5916\uff0c\u8fd8\u6709\u5730\u4e0b\u8d85\u5e02\uff0c\u4e8c\u624b\u4e66\u5e97\uff0c\u4f53\u80b2\u9986\uff0c\u9a7f\u7ad9\uff0c\u64cd\u573a\uff0c\u56fe\u4e66\u9986\uff0c\u6c47\u68ee\u697c\uff0c\u6821\u533b\uff0c\u82b1\u56ed\uff0c\u5c0f\u6e56\u3002 \u5317\u95e8\u6821\u95e8\u5916\u7684\u5730\u65b9\uff0c\u8fc7\u9a6c\u8def\uff0c\u6709\u4e00\u6761\u5c0f\u5403\u8857\uff0c\u5927\u53ef\u53bb\u8f6c\u8f6c\uff0c\u5c1d\u5c1d\uff0c\u4e1c\u95e8\u665a\u4e0a\u7684\u5c0f\u5403\u8857\uff0c\u540c\u7406\u3002 \u5317\u95e8\u5904\uff0c\u4e5f\u6709\u5927\u578b\u8d85\u5e02\uff0c\u836f\u5e97\uff0c\u7b49\uff0c\u4e1c\u95e8\u5904\u4e5f\u6709\u5c0f\u8d85\u5e02\uff0c\u836f\u5e97\uff0c\u5065\u8eab\u623f\uff0c\u81ea\u4e60\u5ba4\u7b49\uff0c\u719f\u6089\u73af\u5883\u5373\u53ef\u3002 \u9664\u4e86\u8fd9\u4e9b\uff0c\u5357\u9633\u662f\u672c\u5730\u6bd4\u8f83\u706b\u7684\u5c31\u662f\u5357\u9633\u5e9c\u8859\uff0c\u79bb\u5b66\u6821\u4e0d\u8fdc\uff0c\u9a91\u7535\u8f66\u6216\u505a\u516c\u4ea4\u8fc7\u6865\u5373\u53ef\u5230\uff0c\u8fd8\u6709\u4e4b\u524d\u7684 360 \u5e7f\u573a\u3002 \u661f\u671f\u5929\uff0c\u4e5f\u53ef\u53bb\u5357\u9633\u5e02\u7684\u4e00\u4e9b\u666f\u533a\u770b\u4e0b\uff0c\u603b\u4e4b\uff0c\u5927\u5b66\u7684\u6bd5\u7adf\u8981\u5728\u8fd9\u91cc\u4f4f\u4e0a\u4e00\u6bb5\u65e5\u5b50\uff0c\u6211\u4eec\u8fd8\u662f\u8981\u719f\u6089\u4e0b\u5f53\u5730\u7684\u73af\u5883\u3002</p> <ul> <li>ing\u2026\u2026</li> </ul>"},{"location":"%E8%80%83%E7%A0%94%E6%B5%81%E7%A8%8B/%E6%96%BD%E5%B7%A5ing.html","title":"\u65bd\u5de5ing","text":""},{"location":"%E8%80%83%E8%AF%81%E5%BB%BA%E8%AE%AE/%E8%AF%81%E4%B9%A6.html","title":"\u8003\u8bc1\u5efa\u8bae","text":"<p>\u5546\u4e1a\u5316\u7b80\u5386\u7684\u4eca\u5929\uff0c\u8bc1\u4e66\u662f\u8bc1\u660e\u4ef7\u503c\u7684\u5229\u5668</p> <p>~~\u8bc1\u4e66\u662f\u53d8\u76f8\u7684\u6559\u80b2\u8003\u8bd5\u6210\u7ee9~~</p>"},{"location":"%E8%80%83%E8%AF%81%E5%BB%BA%E8%AE%AE/%E8%AF%81%E4%B9%A6.html#_2","title":"\u82f1\u8bed\u65b9\u9762","text":"<p>4/6 \u7ea7\u82f1\u8bed\u8bc1\u4e66\u5f88\u91cd\u8981</p> <ul> <li>4/6 \u7ea7\u82f1\u8bed\u6574\u6570\uff0c\u662f\u8eab\u4e3a\u5b66\u751f\u8eab\u4efd\u3002\u624d\u80fd\u8003\u7684\u8bc1\u4e66\uff0c\u4e00\u65e6\u6b65\u5165\u793e\u4f1a\uff0c\u4f60\u53ef\u80fd\u518d\u4e5f\u6ca1\u6709\u673a\u4f1a\u3002</li> <li>\u90e8\u5206\u5de5\u4f5c\u5355\u4f4d\u5e94\u8058\u7684\u786c\u6307\u6807\uff0c\u90e8\u5206\u8003\u7814\u5b66\u6821\u7684\u786c\u6761\u4ef6\u3002</li> <li>\u4e0e 9/2 \u5b66\u6821\u7684\u540c\u53f0\u7ade\u6280\u8d44\u683c</li> <li>\u4e3a \u8003\u7814/\u51fa\u56fd(\u96c5\u601d/\u6258\u798f)\u63d0\u4f9b\u90e8\u5206\u57fa\u7840</li> <li>\u4e3a\u540e\u7eed\u5de5\u4f5c\u5b66\u4e60\u65b0\u6280\u672f\uff0c\u8bfb\u6587\u6863\u63d0\u4f9b\u57fa\u7840</li> </ul>"},{"location":"%E8%80%83%E8%AF%81%E5%BB%BA%E8%AE%AE/%E8%AF%81%E4%B9%A6.html#_3","title":"\u8f6f\u8003","text":"<p>\u5e76\u65e0\u9650\u5236\u5728\u6821\u5927\u5b66\u751f\uff0c\u5728\u6b64\u63d0\u53ca\u91cd\u8981\u6027</p> <ul> <li>\u4e2d\u7ea7\u8bc1\u4e66\uff0c\u90e8\u5206\u5347\u804c\u8bc4\u5b9a\u8981\u6c42\u4ee5\u53ca\u516c\u53f8\u8865\u8d34</li> <li>\u57ce\u5e02\u6237\u53e3\u843d\u6237\u52a0\u5206\u9879</li> </ul>"},{"location":"%E8%80%83%E8%AF%81%E5%BB%BA%E8%AE%AE/%E8%AF%81%E4%B9%A6.html#pta","title":"PTA","text":"<p>\u4ece\u4e8b\u7f16\u7a0b\u6559\u80b2\u8bc1\u4e66</p> <ul> <li>\u9762\u5411\u6b63\u5728\u4ece\u4e8b\u7f16\u7a0b\u6559\u5b66\u5de5\u4f5c\u7684\u6559\u5e08\u548c\u6bd5\u4e1a\u540e\u6709\u610f\u613f\u4ece\u4e8b\u7f16\u7a0b\u6559\u80b2\u7684\u5728\u6821\u5927\u5b66\u751f</li> <li>IT \u6559\u80b2\u673a\u6784\u9700\u8981</li> </ul>"},{"location":"%E8%80%83%E8%AF%81%E5%BB%BA%E8%AE%AE/%E8%AF%81%E4%B9%A6.html#_4","title":"\u8ba1\u7b97\u673a\u4e8c\u7ea7\u8bc1\u4e66\uff1f","text":"<p>\u8eab\u4e3a\u8ba1\u7b97\u673a\u4e13\u4e1a\u9700\u8981\u8003\u8651\u5417\uff1f\u8fd9\u662f\u4e2a\u95ee\u9898</p> <ul> <li>\u8bfb\u7814\u662f\u4e3a\u4e86\u4ea7\u51fa Paper\uff0c\u53ef\u80fd\u9700\u8981</li> <li>\u90e8\u5206\u804c\u4e1a\u9700\u8981\u9891\u7e41\u5904\u7406\u6587\u6863\uff0c\u53ef\u80fd\u9700\u8981</li> </ul>"},{"location":"%E8%80%83%E8%AF%81%E5%BB%BA%E8%AE%AE/%E8%AF%81%E4%B9%A6.html#_5","title":"\u6559\u5e08\u8d44\u683c\u8bc1?","text":"<p>\u5728\u5f53\u4eca\u65f6\u4ee3\uff0c\u4eba\u624d\u8fc7\u5269\uff0c\u4e13\u4e1a\u8981\u5bf9\u53e3</p> <ul> <li>\u5954\u7740\u5f53\u4e00\u540d\u6559\u5e08\uff0c\u800c\u4e14\u662f\u767e\u5206\u4e4b\u4e8c\u767e\u7684\u53ef\u80fd\u6027!</li> </ul>"},{"location":"%E8%80%83%E8%AF%81%E5%BB%BA%E8%AE%AE/%E8%AF%81%E4%B9%A6.html#_6","title":"\u666e\u901a\u8bdd\u8bc1\u4e66\uff1f","text":"<p>\u8003\u5c31\u8003\u4e8c\u7532\uff0c\u4e0d\u7136\u7528\u5904\u4e0d\u5927</p> <ul> <li>\u76ee\u524d\u6bd4\u8f83\u6d41\u884c\u7684 IT \u6559\u80b2\u884c\u4e1a\u53ef\u80fd\u9700\u8981\uff0c\u4f46\u504f\u91cd\u6280\u672f</li> </ul>"},{"location":"%E8%80%83%E8%AF%81%E5%BB%BA%E8%AE%AE/%E8%AF%81%E4%B9%A6.html#_7","title":"\u6b22\u8fce\u8865\u5145\uff01\uff01\uff01\uff01","text":"<p>\u70ed\u70c8\u6b22\u8fce\u8865\u5145</p>"},{"location":"%E8%87%AA%E5%AD%A6%E5%88%86%E6%9E%90/%E6%96%BD%E5%B7%A5ing.html","title":"slef-taught\uff1f","text":"<p>\u4f60\u5728\u5b66\u4ec0\u4e48\uff1f \u4ece\u5f00\u5b66</p>"},{"location":"%E8%87%AA%E5%AD%A6%E5%88%86%E6%9E%90/%E6%96%BD%E5%B7%A5ing.html#search","title":"\u4fe1\u606f Search","text":"<p>\u5a92\u4f53\u6d41\u65f6\u4ee3\uff0cMOOC \u548c B \u7ad9\uff0c\u6210\u4e3a\u5f88\u591a\u4eba\u79f0\u7684\u5927\u5b66\uff0c\u201c\u6211\u5728 B \u7ad9\u4e0a\u5927\u5b66\u201d\u3002</p> <p>\u6709\u4e09\u7c7b\u4eba\uff0cA \u7c7b\u63d0\u524d\u9884\u4e60\uff0cB \u7c7b\u4e0a\u8bfe\u542c\u4e0d\u61c2\uff0c\u8865\u4e60\uff0cC \u7c7b\u53ea\u662f\u671f\u672b\u901f\u6210\uff0c\u8fd9\u4e09\u7c7b\u4eba\u90fd\u662f\u81ea\u5b66\u3002\u627e\u5230\u81ea\u5df1\u6240\u9700\u7684\u662f\u4e00\u4e2a\u5173\u952e\uff0c\u5982\u4f55\u627e\u53c8\u662f\u4e00\u4e2a\u5173\u952e\uff0c\u5728\u6d4f\u89c8\u5668\u4e2d\u7684\u641c\u7d22\u6280\u5de7\uff0c\u662f\u5173\u952e\u5b57\u67e5\u627e\uff0c\u4f8b\u5982\uff0c\u201c\u9ad8\u7b49\u6570\u5b66\u671f\u672b\u901f\u6210\u7f51\u8bfe\u89c6\u9891\u201d\uff0c\u6216\u8bb8\u201c\u9ad8\u7b49\u6570\u5b66 \u671f\u672b \u901f\u6210\u201d\u66f4\u4e3a\u9ad8\u6548\uff0c\u4f46\u662f\u4f60\u7f3a\u5931\u4e86\u51c6\u786e\u4fe1\u606f\uff0c\u662f\u9ad8\u6570\u4e0a\u8fd8\u662f\u9ad8\u6570\u4e0b\u3002\u6709\u65f6\u6362\u4e2a\u6d4f\u89c8\u5668\u6216\u8bb8\u6709\u5947\u6548\u3002</p> <p>\u5b89\u8fea\u6c83\u970d\u5c14\u6240\u8a00\u7684\u65f6\u4ee3\uff0c\u4eba\u4eba\u90fd\u53ef\u6210\u4e3a 5 \u5206\u949f\u540d\u4eba</p>"},{"location":"%E8%87%AA%E5%AD%A6%E5%88%86%E6%9E%90/%E6%96%BD%E5%B7%A5ing.html#_1","title":"\"\u81ea\u5b66\"","text":"<p>\u5411\u672a\u6765\u8fed\u4ee3\u662f\u79c1\u4ee5\u4e3a\u7684\u81ea\u5b66\uff0c\u8fdb\u5316\u5373\u81ea\u5b66\u3002 ......</p>"},{"location":"%E8%87%AA%E5%AD%A6%E5%88%86%E6%9E%90/%E6%96%BD%E5%B7%A5ing.html#_2","title":"\u81ea\u5b66\u5206\u6790","text":"<ul> <li>\u81ea\u5b66\u7684\u574f\u5904\uff0c\u65e0\u6cd5\u83b7\u5f97\u4e00\u4e9b\u8d44\u6e90\uff0c\u6d88\u606f\u6e20\u9053\u53d8\u5c11\uff0c\u4f60\u4f1a\u6000\u7591\u4f60\u662f\u5426\u5728\u778e\u5fd9\u6d3b\uff0c\u81ea\u5b66\u7684\u662f\u5426\u6709\u7528\uff1f ...</li> </ul>"}]}